for UEID = cell1_FIRST_UE_SA, cell12_END_UE_SA do
    if (UEID>=1 and UEID<40) then cellID = 1 uecID = 1
    elseif (UEID>=41 and UEID<80) then cellID = 2 uecID = 2
    elseif (UEID>=81 and UEID<120) then cellID = 3 uecID = 3
    elseif (UEID>=121 and UEID<160) then cellID = 4 uecID = 4
	elseif (UEID>=161 and UEID<200) then cellID = 5 uecID = 5
	elseif (UEID>=201 and UEID<240) then cellID = 6 uecID = 6
	elseif (UEID>=241 and UEID<280) then cellID = 7 uecID = 1
	elseif (UEID>=281 and UEID<320) then cellID = 8 uecID = 2
	elseif (UEID>=321 and UEID<360) then cellID = 9 uecID = 3
	elseif (UEID>=361 and UEID<400) then cellID = 10 uecID = 4
	elseif (UEID>=401 and UEID<440) then cellID = 11 uecID = 5
	elseif (UEID>=441 and UEID<480) then cellID = 12 uecID = 6
    end
    if UEID<=9 then exec('set_ue simulated id='..UEID..' uec='..uecID..' release=15 idle_edrx_cycle_len=2 ptw=2.56 sec_key=0102030405060708090A0B0C0D0EFF0'..UEID..' opc_key=0ED47545168EAFE2C39C075829A7B61F nia=null+zuc+snow3g+aes nea=null+zuc+snow3g+aes suci=0:311:489:0000:0:0:02164590'..UEID..' mode=nr enb=2 rohc=8:rtp,udp cell='..cellID) end
    if (UEID>=10 and UEID<=99) then exec('set_ue simulated id='..UEID..' uec='..uecID..' release=15 idle_edrx_cycle_len=2 ptw=2.56 sec_key=0102030405060708090A0B0C0D0EFF'..UEID..' opc_key=0ED47545168EAFE2C39C075829A7B61F nia=null+zuc+snow3g+aes nea=null+zuc+snow3g+aes suci=0:311:489:0000:0:0:0216459'..UEID..' mode=nr enb=2 rohc=8:rtp,udp cell='..cellID) end
	if UEID>=100 then exec('set_ue simulated id='..UEID..' uec='..uecID..' release=15 idle_edrx_cycle_len=2 ptw=2.56 sec_key=0102030405060708090A0B0C0D0EF'..UEID..' opc_key=0ED47545168EAFE2C39C075829A7B61F nia=null+zuc+snow3g+aes nea=null+zuc+snow3g+aes suci=0:311:489:0000:0:0:021645'..UEID..' mode=nr enb=2 rohc=8:rtp,udp cell='..cellID) end
